import numpy as np
key=np.array([[0,0,3,0],[2,0,3,4],[2,1,1,0],[2,0,0,4]])
targ=np.array([[2,2,2,0],[0,1,0,0],[0,1,3,3],[4,0,4,0]])
mask=key!=0
for k in range(4):
 a=np.rot90(mask,k)
 for f in [False,True]:
  b=np.fliplr(a) if f else a
  if np.array_equal(b,targ!=0): print(k,f)
print('target color counts', {c:int((targ==c).sum()) for c in range(1,5)})

key2=np.array([[0,3,1],[4,3,0],[2,0,4]])
targ2=np.array([[2,2,4],[0,3,3],[4,0,1]])
for k in range(4):
 for f in [False,True]:
  b=np.fliplr(np.rot90(key2!=0,k)) if f else np.rot90(key2!=0,k)
  if np.array_equal(b,targ2!=0):print('match',k,f)
print('rot key',np.rot90(key2,1))
